<?php
/** Proof — rights, slugs, sections, publishing, attachments (spec "Proof", 6 and 7): support → 403 "You may not write articles."; delete without settings.manage → 403; slugs -2 and 422 on a clash; sections save/nest/archive; publish keeps published_at; an article's file through the gate. */
require __DIR__ . '/lib.php';
$W = world();
$owner = as_member(1); $lena = as_member(28); $marco = as_member(27); $priya = as_member(26);
echo "1. Rights\n";
foreach (['/kb/admin/', '/kb/admin/new'] as $p) { $r = page($marco, $p); ok($r['code'] === 403 && str_contains(words($r['body']), 'You may not write articles.'), "support on $p: 403 \"You may not write articles.\""); }
ok(page($priya, '/kb/admin/')['code'] === 403, 'a requester: 403');
foreach (['save.php' => ['title' => 'x', 'body' => 'y'], 'publish.php' => ['article' => 1], 'archive.php' => ['article' => 1], 'section.php' => ['name' => 'x'], 'section-archive.php' => ['section' => 1]] as $h => $form) {
    [$c, $b] = act($marco, '/kb/admin/' . $h, $form);
    ok($c === 403 && msg($b) === 'You may not write articles.', "$h as support: 403 in the sentence");
}
[$a1] = mk_article($lena, 'SMOKE Lena writes', ['status' => 'draft']);
[$c, $b] = act($lena, '/kb/admin/delete.php', ['article' => $a1]);
ok($c === 403 && msg($b) === "You may not change Help Desk's settings.", 'delete without settings.manage (Lena): 403');
ok(page($lena, '/kb/admin/')['code'] === 200 && page($lena, '/kb/admin/new')['code'] === 200 && page($lena, '/kb/admin/' . $a1 . '/edit')['code'] === 200, 'Lena (kb.edit) reaches the desk, the form and the edit page');
echo "2. Slugs\n";
[$s1, $slug1] = mk_article($owner, 'SMOKE Slug test!');
[$s2, $slug2] = mk_article($owner, 'SMOKE Slug test');
ok($slug1 === 'smoke-slug-test' && $slug2 === 'smoke-slug-test-2', 'two articles titled the same: smoke-slug-test, smoke-slug-test-2');
[$c, $b] = act($owner, '/kb/admin/save.php', ['article' => $s1, 'title' => 'SMOKE Slug test, renamed']);
ok($c === 200 && article_row($s1)['slug'] === 'smoke-slug-test' && article_row($s1)['title'] === 'SMOKE Slug test, renamed', 'renaming keeps the slug');
[$c, $b] = act($owner, '/kb/admin/save.php', ['article' => $s1, 'slug' => 'smoke-slug-test-2']);
ok($c === 422 && (fields($b)['slug'] ?? '') === 'That address is taken.', 'a slug clash on edit: 422 "That address is taken."');
[$c, $b] = act($owner, '/kb/admin/save.php', ['article' => $s1, 'slug' => 'Bad Slug']);
ok($c === 422 && isset(fields($b)['slug']), 'a malformed slug: 422');
[$c, $b] = act($owner, '/kb/admin/save.php', ['article' => $s1, 'slug' => 'smoke-slug-howto']);
ok($c === 200 && article_row($s1)['slug'] === 'smoke-slug-howto' && req('GET', '/kb/smoke-slug-howto')['code'] === 200, 'an edited slug is honoured');
echo "3. Validation\n";
[$c, $b] = act($owner, '/kb/admin/save.php', ['title' => '', 'body' => 'x']);
ok($c === 422 && isset(fields($b)['title']), 'no title: 422 by field');
[$c, $b] = act($owner, '/kb/admin/save.php', ['title' => 'SMOKE x', 'body' => 'x', 'visibility' => 'secret']);
ok($c === 422 && isset(fields($b)['visibility']), 'a bad visibility: 422');
[$c, $b] = act($owner, '/kb/admin/save.php', ['title' => 'SMOKE x', 'body' => 'x', 'section' => 99999]);
ok($c === 422 && isset(fields($b)['section']), 'a section that is not here: 422');
echo "4. Sections\n";
$since = last_activity_id();
$top = mk_section($owner, 'SMOKE Accounts', 'public', ['description' => 'SMOKE Passwords and sign-in']);
$child = mk_section($owner, 'SMOKE Passwords', 'public', ['parent' => $top]);
ok($top > 0 && $child > 0 && (int) q('SELECT parent_id FROM kb_sections WHERE id = :s', ['s' => $child])[0]['parent_id'] === $top && count(activity('section.save', $since)) === 2, 'a section and a child; section.save logged twice');
[$c, $b] = act($owner, '/kb/admin/section.php', ['name' => 'SMOKE Deep', 'parent' => $child]);
ok($c === 422 && isset(fields($b)['parent']), 'a child under a child: 422 (one level)');
[$c, $b] = act($owner, '/kb/admin/section.php', ['section' => $top, 'description' => 'SMOKE changed', 'sort_order' => 5]);
ok($c === 200 && q('SELECT description, sort_order, name FROM kb_sections WHERE id = :s', ['s' => $top])[0] == ['description' => 'SMOKE changed', 'sort_order' => 5, 'name' => 'SMOKE Accounts'], 'inline edit changes what was sent and keeps the rest');
[$inChild, $inChildSlug] = mk_article($owner, 'SMOKE Reset your password', ['section' => $child]);
$r = req('GET', '/kb/');
ok(str_contains($r['body'], 'id="kb-section-card-' . $top . '"') && str_contains($r['body'], 'id="kb-section-child-' . $child . '"'), 'the home shows the section with its child nested');
$r = req('GET', '/kb/s/smoke-passwords');
ok($r['code'] === 200 && str_contains($r['body'], 'id="article-row-' . $inChild . '"') && str_contains($r['body'], 'SMOKE Accounts'), "the section page lists its articles under the parent's crumb");
$since = last_activity_id();
[$c, $b] = act($owner, '/kb/admin/section-archive.php', ['section' => $child]);
ok($c === 200 && article_row($inChild)['section_id'] === null && q('SELECT archived_at FROM kb_sections WHERE id = :s', ['s' => $child])[0]['archived_at'] !== null && count(activity('section.archive', $since)) === 1, 'archiving a section: its articles under No section, logged');
ok(req('GET', '/kb/' . $inChildSlug)['code'] === 200 && req('GET', '/kb/s/smoke-passwords')['code'] === 404, 'the article stays reachable by slug; the section page is gone');
ok(str_contains(page($owner, '/kb/admin/?section=0')['body'], 'id="kb-admin-row-' . $inChild . '"'), 'the desk filters No section');
echo "5. Publishing\n";
[$d, $dSlug] = mk_article($owner, 'SMOKE Publish me', ['status' => 'draft']);
ok(article_row($d)['published_at'] === null && req('GET', '/kb/' . $dSlug)['code'] === 404, 'a draft has no published_at and is not public');
$since = last_activity_id();
[$c, $b] = act($owner, '/kb/admin/publish.php', ['article' => $d, 'published' => 'yes']);
$pubAt = article_row($d)['published_at'];
ok($c === 200 && $pubAt !== null && article_row($d)['status'] === 'published' && req('GET', '/kb/' . $dSlug)['code'] === 200 && ($b['published'] ?? null) === true, 'published: published_at set, public');
ok(count(activity('article.publish', $since)) === 1 && json_decode(activity('article.publish', $since)[0]['after'], true)['published'] === true, 'article.publish logged (after.published)');
[$c, $b] = act($owner, '/kb/admin/publish.php', ['article' => $d, 'published' => 'no']);
ok($c === 200 && article_row($d)['status'] === 'draft' && article_row($d)['published_at'] === $pubAt, 'unpublished: a draft again, published_at kept');
[$c, $b] = act($owner, '/kb/admin/save.php', ['article' => $d, 'status' => 'published']);
ok($c === 200 && article_row($d)['status'] === 'published' && article_row($d)['published_at'] === $pubAt, '"Save and publish" on a draft publishes; published_at is not reset');
$r = page($owner, '/kb/' . $dSlug);
ok(str_contains($r['body'], 'id="article-unpublish-btn"') && str_contains($r['body'], 'id="article-archive-btn"') && str_contains($r['body'], 'id="article-edit-link"'), 'an editor sees Edit · Unpublish · Archive');
echo "6. Attachments\n";
$png = tempnam(sys_get_temp_dir(), 'kb') . '.png';
file_put_contents($png, base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=='));
[$c, $b] = upload($owner, '/tickets/attachments/save.php', ['article' => $d], $png);
$att = (int) ($b['attachment_id'] ?? 0);
ok($c === 200 && $att > 0 && (int) q('SELECT article_id FROM attachments WHERE id = :a', ['a' => $att])[0]['article_id'] === $d && ($b['url'] ?? '') === '/kb/attachment.php?id=' . $att, 'attachment_add with article: stored on the article, the url answered');
$r = req('GET', '/kb/attachment.php?id=' . $att);
ok($r['code'] === 200 && str_contains($r['headers'] ?? '', 'image/png'), 'a visitor fetches the public article\'s file');
[$c, $b] = act($owner, '/kb/admin/save.php', ['article' => $d, 'visibility' => 'internal']);
ok(req('GET', '/kb/attachment.php?id=' . $att)['code'] === 404 && page($priya, '/kb/attachment.php?id=' . $att)['code'] === 200, "made internal: the file is 404 to a visitor and served to a member with kb.read");
ok(upload($marco, '/tickets/attachments/save.php', ['article' => $d], $png)[0] === 403, 'support may not attach to an article: 403');
$r = page($owner, '/kb/admin/' . $d . '/edit');
ok(str_contains($r['body'], 'id="article-form-attachment-' . $att . '"') && str_contains($r['body'], '![](/kb/attachment.php?id=' . $att . ')'), 'the edit page lists the file with its Markdown');
echo "7. Delete\n";
$since = last_activity_id();
[$c, $b] = act($owner, '/kb/admin/delete.php', ['article' => $d]);
ok($c === 200 && article_row($d) === [] && count(activity('article.delete', $since)) === 1 && q('SELECT 1 FROM attachments WHERE id = :a', ['a' => $att]) === [], 'deleted with its file; article.delete logged');
ok(leaks(page($owner, '/kb/admin/')['body']) === [], 'the desk leaks nothing');
@unlink($png);
exit($GLOBALS['fails'] === 0 ? 0 : 1);
